{
  "claim": "For non-headline hyperscaler list-price series outside the 14-day gate, using drift alone will reduce pinball loss by matching the series' own frequency and size of discrete repricing.",
  "mechanism": "The hypothesis is that these published medians move through occasional changes to posted offers, with persistence between changes and greater opportunity for another step over longer horizons. Empirical horizon-specific changes from the same series should represent that pattern better than the current blend; the reported ungated hyperscaler-list slice has drift skill +0.205 versus +0.058 for the system.",
  "spec": {
    "when": {
      "all": [
        {"fact": "cls", "op": "==", "value": "hyperscaler_list"},
        {"fact": "gate14", "op": "==", "value": false},
        {"fact": "in37", "op": "==", "value": false}
      ]
    },
    "do": {
      "action": "members_only",
      "members": ["drift"]
    }
  },
  "falsification": "Reject if pooled skill fails to rise overall or in either selection half, fewer than 200 cells across at least five series change, headline skill falls, or fewer than 90% of the 2000 ISO-week block bootstrap resamples show improvement.",
  "prior_ids_used": [],
  "expects": "A modest pooled-skill improvement with headline forecasts unchanged. The aggregate slice supports the direction, but does not establish the gain after excluding headline series, the number of changed cells, or consistency across halves and bootstrap resamples; the fixed test must establish those."
}
